}
html.lq .journey-primary:active,
html.lq .def-focus-cta:active,
html.lq .ent-hero-cta:active,
html.lq .notes-hub-new:active,
html.lq .btn-run:active,
html.lq .next-btn:active,
html.lq .ob-cta:active,
html.lq .plan-next-actions>button:first-child:active,
html.lq .coll-overview-next button:active,
html.lq .ls-nav .ls-next:active,
html.lq .ijl-next:active,
html.lq .pdefi-check:active,
html.lq #scr-lesson .bravo-go:active,
html.lq .ent-reveal-primary:active,
html.lq .pl-adjust-apply:active:not(:disabled),
html.lq .dp-go:active,
html.lq .lq-btn:active{
  transform:translateY(4px)!important;opacity:1!important;
