  border:2px solid var(--line)!important;border-radius:16px!important;
  font-family:var(--display)!important;font-weight:700!important;letter-spacing:0!important;
  box-shadow:0 4px 0 var(--lip)!important;
  transform:translateY(0);
  transition:transform .12s var(--press),box-shadow .12s var(--press),background-color .2s!important;
}
html.lq .plan-next-actions>button+button:active,
html.lq .journey-planning button:active,
html.lq .account-connect:active,
html.lq .jeu-btn:active,
html.lq .ux-card-review:active,
html.lq .ls-nav .ls-prev:active,
html.lq .qf-reset:active,
