html.lq .lq-streak-copy small{font-size:12px;line-height:1;color:var(--ink-2);white-space:nowrap}
html.lq .lq-week{flex:1 1 auto;display:flex;justify-content:space-between;gap:4px;min-width:0}
html.lq .lq-day{flex:0 1 26px;min-width:19px;display:flex;flex-direction:column;align-items:center;gap:3px}
html.lq .lq-day i{position:relative;width:26px;max-width:100%;height:auto;aspect-ratio:1/1;box-sizing:border-box;border-radius:50%;display:grid;place-items:center;background:#fff;box-shadow:inset 0 0 0 1.5px #ECE7FA;font-style:normal}
html.lq .lq-day i svg{width:15px;height:15px;transform-origin:50% 90%}
html.lq .lq-day small{font:700 10px/1 var(--display);color:var(--ink-3)}
html.lq .lq-day.is-done i{background:#FFEAD1;box-shadow:none}
html.lq .lq-day.is-missed .f-o{fill:#E3DDF5}
html.lq .lq-day.is-missed .f-i{fill:#F4F1FC}
html.lq .lq-day.is-today i{background:#FFF9F1;border:2px dashed #FF9A3D;box-shadow:none}
html.lq .lq-day.is-today .f-o{fill:#FFD5AE}
html.lq .lq-day.is-today .f-i{fill:#FFF0DF}
html.lq .lq-day.is-now small{color:var(--ink)}
html.lq .lq-day.is-rest .f-m{fill:#B9B1DC}
html.lq .lq-day.is-future i{background:transparent;border:1.5px dashed #E2DCF5;box-shadow:none}
html.lq .lq-day.is-future .f-o{fill:#E9E5F6}
html.lq .lq-day.is-future .f-i{fill:#F4F2FB}
html.lq .lq-streak:active .lq-day.is-done svg{animation:lqWiggle .5s ease both}
/* Des flammes vivantes (Elisa, 29 octobre, 18 h 07 : « anime les flammes »). La grande flamme danse, son cœur jaune palpite, un halo
   chaud respire autour d’elle et deux étincelles s’envolent ; les flammes des jours faits dansent en vague, chacune avec son décalage. */
html.lq .lq-streak.is-on .lq-streak-flame{position:relative;overflow:visible;animation:lqHalo 2.4s ease-in-out infinite}
html.lq .lq-streak.is-on .lq-streak-flame svg{animation:lqDance 1.7s ease-in-out infinite}
html.lq .lq-streak.is-on .lq-streak-flame .f-i,html.lq .lq-day.is-done .f-i{transform-box:fill-box;transform-origin:50% 100%;animation:lqCore 1.15s ease-in-out infinite}
html.lq .lq-streak.is-on .lq-streak-flame::before,html.lq .lq-streak.is-on .lq-streak-flame::after{content:"";position:absolute;left:50%;top:6px;width:4px;height:4px;margin-left:-2px;border-radius:50%;background:#FFB347;opacity:0;pointer-events:none;animation:lqSpark 2.2s ease-out infinite}
html.lq .lq-streak.is-on .lq-streak-flame::after{width:3px;height:3px;background:#FFD23F;animation-delay:1.1s;animation-duration:2.6s}
html.lq .lq-day.is-done i svg{animation:lqDance 1.9s ease-in-out infinite;animation-delay:calc(var(--d,0) * -.27s)}
html.lq .lq-day.is-done .f-i{animation-delay:calc(var(--d,0) * -.19s)}
@keyframes lqDance{0%,100%{transform:rotate(0) scale(1)}25%{transform:rotate(-5deg) scale(1.05,.95)}50%{transform:rotate(3deg) scale(.96,1.07)}75%{transform:rotate(-2deg) scale(1.03,.98)}}
@keyframes lqCore{0%,100%{transform:scale(1)}30%{transform:scale(.86,1.14)}60%{transform:scale(1.08,.9)}}
@keyframes lqHalo{0%,100%{box-shadow:0 0 0 0 rgba(255,138,30,0)}50%{box-shadow:0 0 14px 3px rgba(255,138,30,.32)}}
@keyframes lqSpark{0%{opacity:0;transform:translate(0,0) scale(1)}15%{opacity:1}100%{opacity:0;transform:translate(6px,-18px) scale(.4)}}
@media (prefers-reduced-motion:reduce){html.lq .lq-streak-flame,html.lq .lq-streak-flame svg,html.lq .lq-streak-flame .f-i,html.lq .lq-day svg,html.lq .lq-day .f-i,html.lq .lq-streak-flame::before,html.lq .lq-streak-flame::after{animation:none!important}}

