html.lq #scr-planning .pl-chips{padding:0!important;gap:0!important;min-height:0!important}
html.lq .pl-chip{
  gap:12px!important;padding:10px 4px 10px 16px!important;border:0!important;border-top:2px solid var(--line-2)!important;border-radius:0!important;
  background:transparent!important;box-shadow:none!important;min-height:64px!important;
}
