html.lq .pl-chip:active{background:var(--surface-2)!important;transform:none!important}
html.lq .pl-chips.is-collapsed>.pl-chip.is-extra{display:none!important}
/* Longue journée : le reste de la liste s'ouvre en bas de la carte. */
html.lq .pl-chips-more{
  display:flex;align-items:center;justify-content:center;gap:8px;width:100%;min-height:56px;box-sizing:border-box;padding:8px 16px;
