  background:#fff;box-shadow:inset 0 0 0 2px var(--lip);color:var(--accent-ink)!important;font:700 14px/1 var(--display)!important;text-align:center;
}
html.lq .pl-chip.ok .cn,html.lq .pl-next-row.ok .cn{background:var(--accent);box-shadow:0 2px 0 var(--accent-lip);color:#fff!important}
html.lq .pl-chip .cn svg,html.lq .pl-next-row .cn svg{width:15px;height:15px}
html.lq .pl-chip .ct,html.lq .pl-next-row .ct{flex:1;min-width:0;overflow:visible!important}
html.lq .pl-chip .ct>span,html.lq .pl-next-row .ct>span{
  display:block!important;-webkit-line-clamp:unset!important;white-space:normal!important;overflow:visible!important;text-overflow:clip!important;
  font-family:var(--display);font-weight:700;font-size:15.5px;line-height:1.25;letter-spacing:-.005em!important;color:var(--ink);overflow-wrap:break-word;
}
html.lq .pl-chip .ct small,html.lq .pl-next-row .ct small{
  display:-webkit-box!important;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden!important;white-space:normal!important;
  margin-top:2px;font-size:13px!important;line-height:1.35;font-weight:450;color:var(--ink-2)!important;
}
html.lq #app .pl-chip .pl-chip-valid,html.lq #app .pl-next-row .pl-chip-valid{
  position:absolute!important;width:1px!important;height:1px!important;margin:-1px!important;padding:0!important;border:0!important;
  overflow:hidden!important;clip-path:inset(50%)!important;white-space:nowrap!important;
}
html.lq .pl-chip .nx{
  flex:none;width:44px!important;height:44px!important;min-height:44px!important;border:0!important;border-radius:14px!important;
  background:transparent!important;box-shadow:none!important;color:var(--ink-3)!important;
}
html.lq .pl-chip .nx:active{background:var(--accent-soft)!important;color:var(--accent-ink)!important;transform:scale(.92)}
/* La séance suivante, sous aujourd'hui */
html.lq .pl-next-day{margin:22px 16px 0}
html.lq .pl-next-head{display:flex;flex-wrap:wrap;align-items:baseline;justify-content:space-between;gap:2px 10px;margin:0 2px 10px}
html.lq .pl-next-head h3{margin:0;font:700 18px/1.2 var(--display);letter-spacing:-.01em;color:var(--ink)}
html.lq .pl-next-head small{flex:none;font-size:13px;color:var(--ink-2)}
html.lq .pl-next-list{display:flex;flex-direction:column;border:2px solid var(--line);border-radius:20px;background:#fff;overflow:hidden}
html.lq .pl-next-row{display:flex;align-items:center;gap:12px;width:100%;min-height:62px;box-sizing:border-box;padding:10px 14px;border:0;background:none;text-align:left;font:inherit;color:inherit;cursor:pointer;-webkit-tap-highlight-color:transparent}
