html.lq .pl-next-row:active{background:var(--surface-2)}
html.lq .planning-progress>summary,html.lq .plan-modules>summary{font-family:var(--display)!important;font-weight:700!important;font-size:17px!important;color:var(--ink)!important}
/* Les deux volets du bas : mêmes marges, même hauteur, « + » au même endroit. */
html.lq #scr-planning .pl-week{padding-bottom:6px!important}
html.lq #scr-planning .pl-hint{margin:14px 24px 0}
@media (max-width:899px){
  html.lq #planning-body>.planning-progress,html.lq #planning-body>.plan-modules{margin:16px 16px 0!important}
  html.lq #planning-body>.plan-modules{margin-bottom:28px!important}
}
