html.lq .pl-overview-adjust{background:#fff!important;color:var(--accent-ink)!important;border:2px solid var(--line)!important;border-radius:14px!important;box-shadow:0 3px 0 var(--lip)!important;font-family:var(--display)!important;font-weight:700!important}
html.lq .pl-overview-adjust:active{transform:translateY(3px);box-shadow:0 0 0 var(--lip)!important}
html.lq .pl-overview-stats b{font-family:var(--display)!important;color:#fff!important;font-size:22px!important}
