html.lq .plan-module-row{border-bottom:2px solid var(--line-2)!important}
html.lq .plan-module-row h3{font-family:var(--display)!important;font-weight:700!important;font-size:16px!important}
html.lq .plan-module-row span{color:var(--accent-ink)!important;font-family:var(--display)!important;font-weight:700!important;text-transform:none!important;letter-spacing:0!important}
