html.lq .plan-module-row progress::-moz-progress-bar{background:var(--accent);border-radius:99px}
html.lq .plan-module-row>button{border:2px solid var(--line)!important;border-radius:14px!important;background:#fff!important;color:var(--accent-ink)!important;box-shadow:0 3px 0 var(--lip)!important;font-family:var(--display)!important;font-weight:700!important;font-size:13.5px!important}
html.lq .plan-module-row>button:active{transform:translateY(3px);box-shadow:0 0 0 var(--lip)!important}
/* Barre du haut : les deux boutons tiennent sur une ligne, sans retour. */
html.lq #scr-planning .planning-toolbar button{white-space:nowrap}
