/* ---------- Animations partagées ---------- */
@keyframes lqRise{from{opacity:0;transform:translateY(14px) scale(.985)}to{opacity:1;transform:none}}
@keyframes lqNodeIn{0%{opacity:0;transform:scale(.3)}60%{opacity:1;transform:scale(1.12)}100%{opacity:1;transform:scale(1)}}
@keyframes lqSlideIn{from{opacity:0;transform:translateX(-8px)}to{opacity:1;transform:none}}
@keyframes lqPulse{0%{transform:scale(.86);opacity:.6}100%{transform:scale(1.32);opacity:0}}
@keyframes lqBob{0%,100%{transform:translateY(0)}50%{transform:translateY(-3px)}}
@keyframes lqFloat{0%,100%{transform:translateY(0) rotate(0)}50%{transform:translateY(-4px) rotate(-2deg)}}
@keyframes lqGrow{from{transform:scaleX(0)}to{transform:scaleX(1)}}
@keyframes lqFlameIn{0%{opacity:0;transform:scale(0) rotate(-25deg)}60%{opacity:1;transform:scale(1.25) rotate(8deg)}100%{opacity:1;transform:scale(1) rotate(0)}}
@keyframes lqFlicker{0%,100%{transform:scale(1) rotate(0)}25%{transform:scale(1.06,.95) rotate(-2.5deg)}50%{transform:scale(.96,1.06) rotate(2deg)}75%{transform:scale(1.03,.98) rotate(-1deg)}}
@keyframes lqWiggle{0%,100%{transform:rotate(0)}25%{transform:rotate(-14deg) scale(1.1)}60%{transform:rotate(10deg) scale(1.08)}}
@keyframes lqTodayPulse{0%,100%{box-shadow:0 0 0 0 rgba(255,154,61,0)}50%{box-shadow:0 0 0 5px rgba(255,154,61,.18)}}
@keyframes lqSegIn{0%{transform:scale(.92)}60%{transform:scale(1.04)}100%{transform:scale(1)}}
@keyframes lqCorrect{0%{transform:scale(1)}35%{transform:scale(1.04)}70%{transform:scale(.99)}100%{transform:scale(1)}}
@keyframes lqShake{0%,100%{transform:translateX(0)}20%{transform:translateX(-7px)}40%{transform:translateX(6px)}60%{transform:translateX(-4px)}80%{transform:translateX(3px)}}
@keyframes lqRunPulse{0%,100%{filter:brightness(1)}50%{filter:brightness(1.12)}}
@keyframes lqHalo{0%,100%{box-shadow:0 0 0 4px rgba(255,255,255,.34),0 3px 0 rgba(20,10,60,.16)}50%{box-shadow:0 0 0 9px rgba(255,255,255,.1),0 3px 0 rgba(20,10,60,.16)}}

/* ---------- 96. Moins de couleurs ----------
   « Fait », « validé », « terminé » prennent le violet de la marque, partout
   dans l'interface. Le vert ne sert plus qu'à « bonne réponse » (quiz,
   exercice, console), le rouge à « erreur », l'orange à la série et aux
   retards. On redirige les jetons du vert vers le violet sur les écrans et
   les pièces concernés ; les retours de réponse gardent leur vert. */
html.lq :is(#scr-learn,#scr-planning,#scr-defis,#scr-collection,#scr-entretien,#scr-compte,#scr-practice,#scr-library,#scr-notes,#scr-jeu,.toast),
html.lq #scr-lesson :is(.ls-steps,.bravo-hero,.bravo-steps,.bravo-done-note,.valid-done,.vsteps,.lesson-status),
html.lq #onboarding :is(.ob-rhythm-min,.ob-practice-run),
html.lq :is(.cd-try-btn,.pl-week-legend){
  --success:var(--accent-ink);--success-soft:var(--accent-soft);--success-fill:var(--accent);--success-lip:var(--accent-lip);
}
/* Étincelles de la carte Bravo : jaune et blanc sur le violet */
html.lq #scr-lesson .bravo-spark:nth-child(odd){background:var(--flame-a)!important}
html.lq #scr-lesson .bravo-spark:nth-child(even){background:#fff!important}
/* Planning : pastille « Validé » ; Mon compte : icônes des chiffres */
html.lq #app .pl-chip-valid{background:var(--accent-soft)!important;color:var(--accent-ink)!important}
html.lq .account-stat-mark,html.lq .account-stat-mark.lessons,html.lq .account-stat-mark.challenges,html.lq .account-stat-mark.progress{
  border:0!important;background:var(--accent-soft)!important;color:var(--accent-ink)!important;box-shadow:none!important;
}
html.lq .account-stat-mark.streak{background:#FFF0DC!important;color:#E05E00!important}

/* ---------- 97. Fluidité : pas de clignotement ----------
   L'ancien thème faisait apparaître en fondu (depuis l'invisible) les cartes,
   listes et puces à chaque fois qu'elles étaient redessinées : au retour sur
   l'accueil, après chaque action, au changement de filtre… L'écran semblait
   clignoter. Ces animations d'entrée sont neutralisées ici (même nom, sans
   effet) ; seules restent celles que la personne déclenche. */
@keyframes iosSurfaceIn{from{opacity:1}to{opacity:1}}
@keyframes iosItemIn{from{opacity:1}to{opacity:1}}
