  html.lq #scr-learn #modules .home-module .row:nth-of-type(6n+2),html.lq #scr-learn #modules .home-module .row:nth-of-type(6n+6){--zz:11px}
  html.lq #scr-lesson .lesson-rich>h1,html.lq #scr-lesson .l-kicker+h1{font-size:32px!important}
  html.lq .coll-grid{gap:10px;padding:4px 12px 14px}
