/* ---------- 17. Progression : graphiques (Avancement global, modules) ---------- */
html.lq #app .planning-progress>summary,html.lq #app .plan-modules>summary{row-gap:7px!important}
.pgr-sum-bar,.pgr-strip{grid-column:1/-1;grid-row:3;display:block;height:8px;margin-top:4px}
.pgr-sum-bar{border-radius:99px;background:var(--surface-2);overflow:hidden}
.pgr-sum-bar b{display:block;height:100%;min-width:6px;border-radius:inherit;background:linear-gradient(90deg,var(--accent),var(--accent-2))}
.pgr-strip{display:grid;grid-auto-flow:column;grid-auto-columns:minmax(0,1fr);gap:3px}
.pgr-strip b{display:block;border-radius:4px;background:var(--line)}
.pgr-strip b.is-done{background:var(--accent)}
.pgr-strip b.is-started{background:linear-gradient(90deg,var(--accent) calc(var(--f)*1%),var(--line) 0)}
.pgr{padding:2px 18px 18px}
.pgr small,.pgr em{font-style:normal}
.pgr-top{display:flex;align-items:center;gap:16px}
.pgr-donut{--p:0;position:relative;flex:none;width:104px;height:104px;display:grid;place-items:center}
.pgr-donut svg{position:absolute;inset:0;width:100%;height:100%;overflow:visible}
.pgr-track{fill:none;stroke:var(--surface-2);stroke-width:12}
.pgr-arc{fill:none;stroke-width:12;stroke-dasharray:var(--len) 251.33;stroke-dashoffset:var(--off);transform:rotate(-90deg);transform-origin:50% 50%;animation:pgrArc .9s cubic-bezier(.3,.7,.3,1) both}
.pgr-arc.is-l{stroke:var(--accent)}
