@keyframes pgrArc{from{stroke-dasharray:0 251.33}to{stroke-dasharray:var(--len) 251.33}}
.pgr-donut>i{position:relative;font:700 26px/1 var(--display);color:var(--ink)}
.pgr-donut>i small{margin-left:1px;font:700 13px var(--display);color:var(--ink-2)}
