.pgr-t-more dt{font:600 11px/1.2 var(--ui);color:var(--ink-3)}
.pgr-t-more dd{margin:3px 0 0;font:700 14px/1.2 var(--display);color:var(--ink);white-space:nowrap}
.pgr-stat.is-t>p{flex:1 1 170px;margin:0;font:500 12px/1.45 var(--ui);color:var(--ink-3)}
/* Temps passé sur un module : petite pastille ⏱ (planning et accueil), jamais coupée. */
.pgr-mod-time,.home-module-time{display:inline-flex;align-items:center;gap:4px;margin-left:7px;padding:2px 8px 2px 6px;border-radius:999px;background:var(--surface-2);color:var(--ink-2);font:700 11px/1.35 var(--ui);white-space:nowrap;vertical-align:1px}
.pgr-mod-time svg,.home-module-time svg{flex:none;width:11px;height:11px;color:#0F9F86}
.pgr-chart{margin-top:16px;padding:14px 12px 13px;border:2px solid var(--line-2);border-radius:18px;background:#fff}
.pgr-chart-h{display:flex;align-items:baseline;justify-content:space-between;gap:4px 10px;flex-wrap:wrap}
.pgr-chart-h b{font:700 16px var(--display);color:var(--ink)}
.pgr-chart-h small{font:600 12px var(--ui);color:var(--ink-2)}
.pgr-bars{list-style:none;margin:14px 0 0;padding:0;display:grid;grid-template-columns:repeat(14,minmax(0,1fr));gap:4px;height:118px;align-items:end;background:linear-gradient(var(--line-2),var(--line-2)) 0 calc(100% - 22px)/100% 2px no-repeat}
.pgr-bars li{display:flex;flex-direction:column;align-items:center;justify-content:flex-end;height:100%;min-width:0}
.pgr-bars li em{font:700 10.5px/1 var(--display);color:var(--accent-ink);margin-bottom:3px;min-height:10px}
.pgr-bars li>i{display:block;width:100%;max-width:20px;height:calc(var(--h)*.74px);min-height:6px;border-radius:7px 7px 3px 3px;background:var(--line-2);transform-origin:bottom;animation:pgrBar .6s cubic-bezier(.3,.8,.3,1.1) both;animation-delay:calc(var(--k,0)*32ms)}
.pgr-bars li.is-done>i{background:linear-gradient(180deg,var(--accent-2),var(--accent))}
.pgr-bars li.is-rest>i{background:repeating-linear-gradient(135deg,var(--line-2) 0 3px,#fff 3px 6px)}
