@keyframes pgrBar{from{transform:scaleY(0)}to{transform:none}}
.pgr-trend{margin:11px 0 0;font:500 12.5px/1.45 var(--ui);color:var(--ink-2)}
.pgr-trend b{color:var(--ink);font-weight:700}
.pgr-next{margin-top:16px;padding:14px;border-radius:18px;background:var(--surface-2)}
.pgr-next>span{display:block;min-width:0}
.pgr-next small{display:block;font:700 10.5px/1.2 var(--ui);letter-spacing:.07em;text-transform:uppercase;color:var(--accent-ink)}
.pgr-next>span>b{display:block;margin-top:4px;font:700 17px/1.25 var(--display);color:var(--ink)}
.pgr-next>span>em{display:block;margin-top:4px;font:500 12.5px/1.4 var(--ui);color:var(--ink-2)}
.pgr-actions{display:flex;gap:8px;margin-top:13px}
.pgr-go{flex:1;min-width:0;min-height:48px;padding:0 14px;display:flex;align-items:center;justify-content:center;gap:6px;border:0;border-radius:15px;background:var(--accent);color:#fff;font:700 15px var(--display);box-shadow:0 4px 0 var(--m-lip,#4B30CC);cursor:pointer;-webkit-tap-highlight-color:transparent}
.pgr-go:active{transform:translateY(4px);box-shadow:none}
.pgr-go svg{width:17px;height:17px}
