.pgr-go:focus-visible,.pgr-tile:focus-visible,.pgr-chip:focus-visible,.pgr-mod>button:focus-visible{outline:3px solid var(--accent);outline-offset:2px}
/* Par module */
.pgr-head{display:flex;align-items:flex-end;justify-content:space-between;gap:10px 14px;flex-wrap:wrap}
.pgr-head b{font:700 30px/1 var(--display);color:var(--ink)}
.pgr-head b em{margin-left:2px;font:600 15px var(--ui);color:var(--ink-3)}
.pgr-head small{display:block;margin-top:4px;font:600 12.5px var(--ui);color:var(--ink-2)}
.pgr-legend{list-style:none;margin:0;padding:0;display:flex;gap:4px 12px;flex-wrap:wrap;font:600 11.5px var(--ui);color:var(--ink-2)}
.pgr-legend li::before{content:'';display:inline-block;width:9px;height:9px;margin-right:5px;border-radius:50%;vertical-align:-1px;background:var(--line)}
.pgr-legend .is-done::before{background:var(--accent)}
.pgr-legend .is-started::before{background:linear-gradient(90deg,var(--accent) 50%,var(--line) 0)}
.pgr-map{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;margin-top:14px}
.pgr-tile{display:flex;flex-direction:column;align-items:center;gap:6px;padding:11px 4px 9px;border:2px solid var(--line-2);border-radius:16px;background:#fff;font:inherit;cursor:pointer;-webkit-tap-highlight-color:transparent;transition:transform .15s,border-color .15s}
.pgr-tile:active{transform:scale(.95)}
.pgr-tile.is-done{border-color:#D9CFFF;background:#FBFAFF}
.pgr-tile>small{font:700 11.5px var(--ui);color:var(--ink-2);font-variant-numeric:tabular-nums}
.pgr-ring{--f:0;position:relative;flex:none;display:grid;place-items:center;width:46px;height:46px;border-radius:50%;background:conic-gradient(var(--accent) calc(var(--f)*1%),var(--line-2) 0)}
.pgr-ring::after{content:'';position:absolute;inset:5px;border-radius:50%;background:#fff}
.pgr-ring span{position:relative;z-index:1;display:grid;place-items:center;font:700 13px var(--display);color:var(--ink-3)}
.pgr-ring span svg{width:19px;height:19px}
.is-started .pgr-ring span{color:var(--accent-ink)}
.is-done .pgr-ring{background:var(--accent)}
.is-done .pgr-ring::after{background:var(--accent)}
.is-done .pgr-ring span{color:#fff}
.pgr-filter{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin:16px 0 0;padding:0 0 8px}
