}
@keyframes pgrFlash{0%,65%{box-shadow:0 0 0 4px rgba(106,77,244,.4)}100%{box-shadow:0 0 0 0 rgba(106,77,244,0)}}
.pgr-empty{margin:8px 2px 2px;font:500 13.5px/1.5 var(--ui);color:var(--ink-2)}
.pgr-sr{position:absolute;width:1px;height:1px;margin:-1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
@media (max-width:359px){
  .pgr{padding-left:14px;padding-right:14px}
  .pgr-top{gap:12px}.pgr-donut{width:88px;height:88px}.pgr-donut>i{font-size:22px}
  .pgr-stats{gap:6px}.pgr-stat{padding:9px 8px 10px}.pgr-stat>b,.pgr-t-main>b{font-size:21px}
