@keyframes mstkBurst{0%{opacity:0;transform:translate(0,0) rotate(0) scale(.3)}14%{opacity:1}75%{opacity:1}100%{opacity:0;transform:translate(var(--x),var(--y)) rotate(var(--r)) scale(1)}}
