    linear-gradient(rgba(255,255,255,.06) 1px,transparent 1px) 0 0/30px 30px,linear-gradient(90deg,rgba(255,255,255,.06) 1px,transparent 1px) 0 0/30px 30px}
html.lq .lv-video{background:transparent}
html.lq .lv-ico,html.lq .lv-chip{border-color:#fff;box-shadow:0 3px 0 rgba(20,10,60,.3)}
html.lq .lv-ico:active,html.lq .lv-chip:active{box-shadow:0 0 0 rgba(20,10,60,.3)}
html.lq .lv-chip.is-set{background:var(--sun-soft,#FFF4D6);border-color:#fff;color:#1B1640}
html.lq .lv-big{background:var(--sun);color:#1B1640;box-shadow:0 5px 0 var(--sun-lip),0 18px 40px -16px rgba(10,4,60,.6)}
html.lq .lv-time{color:rgba(255,255,255,.84)}
html.lq .lv-rail{background:rgba(255,255,255,.24)}
html.lq .lv-fill{background:#fff}
html.lq .lv-knob::before{border-color:var(--sun);background:#fff;box-shadow:0 2px 6px rgba(10,4,60,.4)}
html.lq .lv.is-valid .lv-knob::before{border-color:var(--mint);box-shadow:0 0 0 6px rgba(159,240,198,.3),0 2px 6px rgba(10,4,60,.4)}
html.lq .lv-c{color:#fff}
html.lq .lv-c:active{background:rgba(255,255,255,.14)}
html.lq .lv-c.lv-pp{background:var(--sun);color:#1B1640;box-shadow:0 4px 0 var(--sun-lip)}
html.lq .lv-c.lv-pp:active{background:var(--sun);box-shadow:0 1px 0 var(--sun-lip)}
html.lq .lv-dt{background:rgba(255,255,255,.16);color:#fff}
html.lq .lv-end{background:rgba(30,16,92,.5)}
html.lq .lv-note-arrow path{stroke:#fff}
html.lq .lv-note-arrow .lv-a-halo{stroke:var(--sun-hi);opacity:.35}

/* ---------- 36. Feuilles, page d’un projet, question d’entretien, pas à pas : la DA de la vitrine ----------
   Elisa, 30 octobre, 22 h 11 : « à passer au niveau supérieur (stickers ? animation ? couleur et DA du site ?) ». Partout le même
   langage que l’accueil et la vitrine : le violet profond quadrillé avec sa lueur jaune et son étincelle, les titres en jaune soleil,
   les pastilles menthe, des autocollants découpés (lqStkSvg : contour blanc, ombre à rebord peinte, net sur iPhone) qui se collent
   d’un claquement puis flottent, des cartes blanches à rebord. */
@keyframes lqAskSlap{0%{opacity:0;transform:translateY(-12px) rotate(-16deg) scale(1.6)}50%{opacity:1;transform:translateY(2px) rotate(4deg) scale(.92)}74%{transform:rotate(-2deg) scale(1.04)}100%{opacity:1;transform:none}}
@keyframes lqAskUp{from{opacity:0;transform:translateY(10px)}}
@keyframes lqWave{0%,100%{transform:scaleY(.45)}50%{transform:scaleY(1)}}
html.lq .lq-stk{display:block;width:100%;height:100%;overflow:visible}
html.lq .lq-stk-wave path{transform-box:fill-box;transform-origin:center;animation:lqWave 1.1s ease-in-out infinite}
html.lq .lq-stk-wave path:nth-child(2){animation-delay:-.25s}
html.lq .lq-stk-wave path:nth-child(3){animation-delay:-.5s}
html.lq .lq-stk-wave path:nth-child(4){animation-delay:-.75s}
html.lq .lq-stk-wave path:nth-child(5){animation-delay:-.95s}

/* Les feuilles (lqAsk, lqPrompt) : un bandeau violet en tête, l’autocollant, le titre en jaune ; champ et boutons sur le blanc. */
html.lq .lq-ask-sheet{padding:0 20px 20px;overflow:hidden}
html.lq .lq-ask-cap{position:relative;isolation:isolate;margin:0 -20px 20px;padding:24px 24px 22px;background:var(--deep);color:#fff}
html.lq .lq-ask-cap::before{content:"";position:absolute;inset:0;z-index:-1;pointer-events:none;
  background:radial-gradient(240px 190px at 90% 0%,rgba(255,216,107,.3),transparent 70%),radial-gradient(220px 170px at 0% 100%,rgba(159,240,198,.16),transparent 70%),
    linear-gradient(rgba(255,255,255,.07) 1px,transparent 1px) 0 0/26px 26px,linear-gradient(90deg,rgba(255,255,255,.07) 1px,transparent 1px) 0 0/26px 26px;
  -webkit-mask-image:radial-gradient(ellipse 100% 95% at 60% 10%,#000 35%,transparent 95%);mask-image:radial-gradient(ellipse 100% 95% at 60% 10%,#000 35%,transparent 95%)}
html.lq .lq-ask-cap.is-danger::before{background:radial-gradient(240px 190px at 90% 0%,rgba(255,128,128,.36),transparent 70%),radial-gradient(220px 170px at 0% 100%,rgba(255,216,107,.12),transparent 70%),
    linear-gradient(rgba(255,255,255,.07) 1px,transparent 1px) 0 0/26px 26px,linear-gradient(90deg,rgba(255,255,255,.07) 1px,transparent 1px) 0 0/26px 26px}
html.lq .lq-ask-cap::after{content:"";position:absolute;right:20px;top:18px;width:16px;height:16px;pointer-events:none;background:#fff;
  -webkit-mask:var(--mstk-star) center/contain no-repeat;mask:var(--mstk-star) center/contain no-repeat;animation:lqTwinkle 3.2s ease-in-out infinite}
html.lq .lq-ask-stk{display:block;width:74px;height:74px;margin:0 auto 12px;rotate:-6deg}
html.lq .lq-ask-stk>svg{animation:mstkFloat 5.2s ease-in-out 1.1s infinite}
html.lq .lq-ask.on .lq-ask-stk{animation:lqAskSlap .7s cubic-bezier(.3,.7,.3,1) .14s both}
html.lq .lq-ask-stk.is-badge{display:grid;place-items:center;width:58px;height:58px;box-sizing:border-box;border-radius:20px;background:#6A4DF4;color:#fff;
  border:2.5px solid #1B1640;box-shadow:0 0 0 4px #fff,0 6px 0 4px rgba(27,22,64,.28);font-size:27px;line-height:1}
html.lq .lq-ask-stk.is-badge i{display:grid;place-items:center;font-style:normal}
html.lq .lq-ask-stk.is-badge svg{width:27px;height:27px;display:block}
html.lq .lq-ask .lq-ask-cap h2{color:var(--sun-hi);text-wrap:balance;overflow-wrap:anywhere}
html.lq .lq-ask .lq-ask-cap p{margin:8px 0 0;color:rgba(255,255,255,.88);text-wrap:pretty}
html.lq .lq-ask.on .lq-ask-cap h2{animation:lqAskUp .4s ease-out .18s both}
html.lq .lq-ask.on .lq-ask-cap p{animation:lqAskUp .4s ease-out .24s both}
html.lq .lq-ask.on .lq-ask-field,html.lq .lq-ask.on .lq-ask-btns{animation:lqAskUp .42s ease-out .28s both}
html.lq .lq-ask-btns{margin-top:0}
/* Avec un champ : bandeau compact (le clavier prend la moitié de l’écran), l’autocollant à gauche du titre */
html.lq .lq-ask.has-field .lq-ask-sheet{padding-top:0}
html.lq .lq-ask.has-field .lq-ask-cap{display:flex;align-items:center;gap:14px;margin-bottom:16px;padding:18px 40px 18px 18px;text-align:left}
html.lq .lq-ask.has-field .lq-ask-stk{flex:none;width:58px;height:58px;margin:0}
html.lq .lq-ask.has-field .lq-ask-stk.is-badge{width:50px;height:50px;border-radius:17px;font-size:23px}
html.lq .lq-ask-cap-t{flex:1;min-width:0}
html.lq .lq-ask.has-field .lq-ask-cap h2{font-size:21px;line-height:1.15;text-wrap:balance}
html.lq .lq-ask.has-field .lq-ask-cap p{margin:5px 0 0;font-size:14.5px;line-height:1.4}
html.lq .lq-ask.has-field .lq-ask-field{margin:0}
html.lq .lq-ask-field input,html.lq .lq-ask-field textarea{border-color:#E1DAFF;background:#F7F5FF;border-radius:18px;box-shadow:inset 0 2px 0 rgba(27,22,64,.04)}
html.lq .lq-ask-field input:focus,html.lq .lq-ask-field textarea:focus{border-color:var(--accent);background:#fff;box-shadow:0 0 0 4px var(--accent-soft)}
html.lq .lq-ask-field small{width:max-content;margin:8px 2px 0 auto;padding:4px 9px;border-radius:99px;background:var(--accent-soft);color:var(--accent-ink);font:700 12px/1 var(--display);transition:background .2s,color .2s}
html.lq .lq-ask-field small.is-near{background:#FFF1C9;color:#8A5A00}
html.lq .lq-ask-field small.is-max{background:#FFE1E1;color:#B4232C}
html.lq .lq-ask.has-field .lq-ask-btns{margin-top:14px}
@media (max-width:360px){
  html.lq .lq-ask-cap{padding:20px 18px 18px}
  html.lq .lq-ask-stk{width:64px;height:64px}
  html.lq .lq-ask.has-field .lq-ask-cap{padding:16px 34px 16px 16px;gap:12px}
  html.lq .lq-ask.has-field .lq-ask-stk{width:50px;height:50px}
  html.lq .lq-ask.has-field .lq-ask-cap h2{font-size:19px}
}

/* Planning : « Auj. » (revenir à la semaine en cours) était blanc sur blanc ; un jour passé sans séance n’invite plus à y glisser une
   leçon, et un jour libre rappelle où sont les défis. */
html.lq .wk-nav>.wk-now{width:auto!important;min-width:0!important;padding:0 12px!important;background:var(--accent)!important;border-color:var(--accent)!important;color:#fff!important;
  box-shadow:0 3px 0 var(--accent-lip)!important;font:700 13.5px/1 var(--display)!important}
html.lq .wk-nav>.wk-now:active{box-shadow:0 0 0 var(--accent-lip)!important}
html.lq .dp-pause .dp-defis{display:inline-flex;align-items:center;gap:6px;margin:10px 0 0;padding:9px 12px 9px 14px;border:2px solid var(--line);border-radius:14px;background:#fff;
  box-shadow:0 3px 0 var(--lip);color:var(--accent-ink);font:700 13.5px/1.25 var(--display);text-align:left;cursor:pointer;-webkit-tap-highlight-color:transparent;transition:transform .12s var(--press),box-shadow .12s var(--press)}
html.lq .dp-pause .dp-defis:active{transform:translateY(3px);box-shadow:0 0 0 var(--lip)}
html.lq .dp-pause .dp-defis svg{flex:none;width:15px;height:15px}
html.lq .dp-pause.is-past .dp-pi{background:#EFEDF8;font-size:17px}
/* Compte : le premier des 7 jours s’appelle « Auj. » ; sur un petit écran, le compte des séances passe sous le titre */
html.lq .acct-day.is-today small{color:var(--accent-ink);white-space:nowrap}
html.lq .acct-week-card .acct-card-head{flex-wrap:wrap;row-gap:2px}
html.lq .acct-week-card .acct-card-head b{white-space:nowrap}

/* La page d’un projet : son nom sur la carte violette de l’accueil (pastille menthe, titre jaune), la base collée en autocollant,
   la description en blanc ; onglets, schéma et exemples à rebord comme les autres cartes. */
html.lq #scr-console .console-title-row.is-project{display:block}
html.lq #scr-console .console-title-row.is-project>div:first-child{position:relative;isolation:isolate;display:flex;flex-direction:column;align-items:flex-start;margin:4px 0 2px;padding:16px 16px 16px;
  border-radius:28px;background:var(--deep);color:#fff;box-shadow:0 6px 0 #3A22B0,0 26px 44px -26px rgba(40,20,140,.55);animation:lvHeroIn .5s var(--press,cubic-bezier(.3,.7,.4,1)) backwards}
html.lq #scr-console .console-title-row.is-project>div:first-child::before{content:"";position:absolute;inset:0;z-index:-1;pointer-events:none;border-radius:inherit;
  background:radial-gradient(260px 220px at 92% 0%,rgba(255,216,107,.26),transparent 70%),radial-gradient(240px 200px at 0% 100%,rgba(159,240,198,.16),transparent 70%),
    linear-gradient(rgba(255,255,255,.07) 1px,transparent 1px) 0 0/28px 28px,linear-gradient(90deg,rgba(255,255,255,.07) 1px,transparent 1px) 0 0/28px 28px;
  -webkit-mask-image:radial-gradient(ellipse 95% 85% at 70% 20%,#000 30%,transparent 90%);mask-image:radial-gradient(ellipse 95% 85% at 70% 20%,#000 30%,transparent 90%)}
html.lq #scr-console .console-title-row.is-project>div:first-child::after{content:"";position:absolute;right:26px;top:80px;width:15px;height:15px;pointer-events:none;background:#fff;
  -webkit-mask:var(--mstk-star) center/contain no-repeat;mask:var(--mstk-star) center/contain no-repeat;animation:lqTwinkle 3.2s ease-in-out infinite}
html.lq #scr-console .console-hero-stk{display:none}
html.lq #scr-console .is-project .console-hero-stk{position:absolute;z-index:2;right:10px;top:-14px;display:block;width:80px;height:80px;rotate:9deg;pointer-events:none;animation:lvPrizeF 4.8s ease-in-out 1s infinite}
html.lq #scr-console .console-title-row.is-project p.sub{order:-1;display:inline-flex;align-items:center;gap:8px;max-width:calc(100% - 66px);margin:0;padding:4px 11px 4px 4px;border-radius:14px;
  background:rgba(255,255,255,.14);box-shadow:inset 0 0 0 1.5px rgba(255,255,255,.22);color:#fff;font:600 13px/1.25 var(--display);letter-spacing:0}
html.lq #scr-console .console-title-row.is-project p.sub b{flex:none;padding:3px 9px;border-radius:10px;background:var(--mint);color:#1B1640;font-weight:700}
html.lq #scr-console .console-title-row.is-project p.sub span{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
html.lq #app #scr-console .console-title-row.is-project h1{margin:12px 0 0;padding-right:72px;color:var(--sun-hi);font-size:34px;line-height:1.02}
html.lq #app #scr-console .console-title-row.is-project h1.is-long{font-size:26px;line-height:1.1}
html.lq #scr-console .is-project .console-desc{max-width:none;margin:14px 0 0;padding:11px 12px 11px 14px;border:1.5px solid rgba(255,255,255,.24);background:rgba(255,255,255,.1);
  box-shadow:none;color:rgba(255,255,255,.92);font-size:14.5px}
html.lq #scr-console .is-project .console-desc:active{transform:scale(.985);box-shadow:none}
html.lq #scr-console .is-project .console-desc i{display:grid;place-items:center;width:28px;height:28px;margin:-4px -2px -4px 0;border-radius:50%;background:var(--sun);color:#1B1640;opacity:1;box-shadow:0 2px 0 var(--sun-lip)}
html.lq #scr-console .is-project .console-desc i svg{width:15px;height:15px}
html.lq #scr-console .is-project .console-desc.is-empty{border-style:dashed;border-color:rgba(255,255,255,.5);background:transparent;color:#fff}
html.lq #scr-console .is-project .console-desc.is-empty i{margin:0;width:24px;height:24px}
/* Onglets : une piste lilas, l’onglet choisi posé dessus à rebord, ses compteurs en pastilles */
html.lq #scr-console .console-project-tabs{height:54px;padding:4px;border:2px solid var(--line);border-radius:19px;background:#EEEAFE;box-shadow:none}
html.lq #scr-console .console-project-tab{border-radius:14px;color:var(--ink-2);font:700 14px/1 var(--display);letter-spacing:-.01em;gap:6px}
html.lq #scr-console .console-project-tab.on{background:#fff;color:var(--accent-ink);box-shadow:0 3px 0 var(--lip)}
html.lq #scr-console .console-project-tab span{background:#fff;color:var(--ink-3);font:700 11px/1 var(--display);box-shadow:inset 0 0 0 1.5px var(--line)}
html.lq #scr-console .console-project-tab.on span{background:var(--accent);color:#fff;box-shadow:none}
/* Schéma : carte à rebord, « Voir » en pastille */
html.lq #scr-console .console-schema-summary{border:2px solid var(--line);border-radius:22px;box-shadow:0 3px 0 var(--lip);transition:transform .12s var(--press),box-shadow .12s var(--press)}
html.lq #scr-console .console-schema-summary:active{transform:translateY(3px);box-shadow:0 0 0 var(--lip);background:#fff}
html.lq #scr-console .console-schema-summary b{font-family:var(--display);font-size:17px}
html.lq #scr-console .console-schema-action{padding:6px 11px;border-radius:99px;background:var(--accent-soft);color:var(--accent-ink);font:700 13px/1 var(--display)}
/* Exemples : chaque carte dit ce qu’elle fait et montre sa requête, colorée comme dans l’éditeur */
html.lq #scr-console .chips-wrap .db-lab span{font:700 15px/1.2 var(--display);color:var(--ink)}
html.lq #scr-console .chip.console-ex{display:flex;flex-direction:column;align-items:stretch;gap:8px;width:auto;max-width:236px;min-height:0;padding:9px 9px 9px;
  border:2px solid var(--line);border-radius:18px;background:#fff;box-shadow:0 3px 0 var(--lip);text-align:left;white-space:normal;color:var(--ink);font-family:var(--display);
  transition:transform .12s var(--press),box-shadow .12s var(--press)}
html.lq #scr-console .chip.console-ex:active{transform:translateY(3px);box-shadow:0 0 0 var(--lip)}
html.lq #scr-console .chip.console-ex small{display:flex;align-items:center;gap:7px;padding:1px 3px 0;font:700 13.5px/1.2 var(--display);color:var(--ink);white-space:nowrap}
html.lq #scr-console .chip.console-ex small i{display:grid;place-items:center;flex:none;width:20px;height:20px;border-radius:50%;background:var(--sun);color:#1B1640;box-shadow:0 2px 0 var(--sun-lip)}
html.lq #scr-console .chip.console-ex small i svg{width:11px;height:11px;margin-left:1px}
html.lq #scr-console .chip.console-ex code{flex:1 1 auto;display:flex;align-items:center;min-width:150px;padding:8px 10px;border-radius:11px;
  background:#1B1640;color:#E9E5FF;font:600 12px/1.35 var(--mono)}
html.lq #scr-console .chip.console-ex code>span{display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2;white-space:normal;overflow:hidden;overflow-wrap:anywhere}
html.lq #scr-console .chip.console-ex code .t-kw{color:#B9A8FF}
html.lq #scr-console .chip.console-ex code .t-fn{color:var(--mint)}
html.lq #scr-console .chip.console-ex code .t-num{color:var(--sun-hi)}
html.lq #scr-console .chip.console-ex code .t-str{color:#FFB8D8}

/* Question d’entretien : la question sur la carte violette (pastilles, titre jaune, micro en autocollant, onde menthe qui parle),
   la réponse sur une carte blanche à rebord avec la bulle collée dessus. */
html.lq .ent-focus-hero{position:relative;isolation:isolate;margin:6px 0 16px;padding:16px 16px 17px;border-radius:28px;background:var(--deep);color:#fff;
  box-shadow:0 6px 0 #3A22B0,0 26px 44px -26px rgba(40,20,140,.55)}
html.lq .ent-focus-hero::before{content:"";position:absolute;inset:0;z-index:-1;pointer-events:none;border-radius:inherit;
  background:radial-gradient(260px 220px at 92% 0%,rgba(255,216,107,.26),transparent 70%),radial-gradient(240px 200px at 0% 100%,rgba(159,240,198,.16),transparent 70%),
    linear-gradient(rgba(255,255,255,.07) 1px,transparent 1px) 0 0/28px 28px,linear-gradient(90deg,rgba(255,255,255,.07) 1px,transparent 1px) 0 0/28px 28px;
  -webkit-mask-image:radial-gradient(ellipse 95% 85% at 70% 20%,#000 30%,transparent 90%);mask-image:radial-gradient(ellipse 95% 85% at 70% 20%,#000 30%,transparent 90%)}
/* L’étoile scintille sous l’ampoule, à l’écart des flèches du haut (6 novembre, 22 h 56) */
html.lq .ent-focus-hero::after{content:"";position:absolute;right:30px;top:80px;width:15px;height:15px;pointer-events:none;background:#fff;
  -webkit-mask:var(--mstk-star) center/contain no-repeat;mask:var(--mstk-star) center/contain no-repeat;animation:lqTwinkle 3.2s ease-in-out infinite}
html.lq .ent-focus-stk{position:absolute;z-index:2;right:12px;top:-16px;width:76px;height:76px;rotate:10deg;pointer-events:none;animation:lvPrizeF 4.8s ease-in-out 1s infinite}
html.lq .ent-focus .ent-focus-meta{flex-wrap:wrap;gap:6px;max-width:calc(100% - 84px);color:#fff;font:600 13px/1.25 var(--display)}
html.lq .ent-focus .ent-focus-meta b{color:var(--sun-hi);font:800 13px/1 var(--display)}
html.lq .ent-focus .ent-focus-meta>i{display:none}
html.lq .ent-focus .ent-focus-meta>span:last-child{padding:5px 10px;border-radius:12px;background:var(--mint);color:#1B1640;font-weight:700}
html.lq .ent-focus .ent-focus-hero h1{margin:14px 0 12px;color:var(--sun-hi);font:700 31px/1.06 var(--display);letter-spacing:-.025em;text-wrap:balance}
html.lq .ent-focus .ent-coach{margin:0;color:rgba(255,255,255,.9);font:600 14.5px/1.35 var(--display)}
html.lq .ent-focus .ent-wave{display:flex;align-items:center;justify-content:center;gap:3px;width:34px;height:30px;border-radius:10px;background:rgba(255,255,255,.14)}
html.lq .ent-focus .ent-wave i{display:block;width:3px;height:14px;border-radius:2px;background:var(--mint);animation:lqWave 1.1s ease-in-out infinite}
html.lq .ent-focus .ent-wave i:nth-child(1){height:7px;animation-delay:-.2s}
html.lq .ent-focus .ent-wave i:nth-child(2){animation-delay:-.45s}
html.lq .ent-focus .ent-wave i:nth-child(3){height:18px;animation-delay:-.7s}
html.lq .ent-focus .ent-wave i:nth-child(4){animation-delay:-.95s}
html.lq .ent-focus .ent-wave i:nth-child(5){height:8px;animation-delay:-.1s}
html.lq .ent-focus .ent-answer-card{border:2px solid var(--line);border-radius:26px;background:#fff;box-shadow:0 4px 0 var(--lip)}
html.lq .ent-focus .ent-answer-lock{padding:10px 4px 6px}
html.lq .ent-focus .ent-answer-lock-ico{width:72px;height:72px;margin:-4px auto 10px;border-radius:0;background:none;box-shadow:none;rotate:-7deg;animation:mstkFloat 5.2s ease-in-out infinite}
html.lq .ent-focus .ent-answer-lock-ico svg{width:72px;height:72px}
html.lq .ent-focus:not(.ent-static) .ent-answer-lock-ico{animation:lqAskSlap .7s cubic-bezier(.3,.7,.3,1) .2s both,mstkFloat 5.2s ease-in-out 1.1s infinite}
html.lq .ent-focus .ent-answer-lock b{font:700 20px/1.2 var(--display);letter-spacing:-.015em;color:var(--ink)}
html.lq .ent-focus .ent-answer-lock p{color:var(--ink-2);font-size:14.5px}
