  82%{opacity:1;transform:scale(1.07);animation-timing-function:cubic-bezier(.3,0,.3,1)}
  100%{opacity:1;transform:none}}
@keyframes introVoile{0%{opacity:1}40%,100%{opacity:0}}
@keyframes introNombre{0%,30%{opacity:0}60%,100%{opacity:.9}}
/* La soudure : chaque case grandit jusqu’à toucher ses voisines (128 / 112, un peu plus pour qu’aucun fil de jour ne reste entre
   elles), seuls les coins de la touche restent arrondis ; seule la
   rangée du bas garde son épaisseur (--ombre), celle des autres ne déborde pas sur leurs voisines */
@keyframes introSoude{from{transform:none}to{transform:scale(1.152)}}
/* Les coins et l’épaisseur changent d’un coup au début de la soudure (une animation à part, d’une milliseconde : elle ne retient pas
   l’agrandissement sur le fil principal) */
@keyframes introCoins{to{border-radius:var(--rf);box-shadow:0 calc(8*var(--u)) 0 var(--ombre,#4B30CC)}}
/* La touche entière : elle tombe sur son socle (un coup net), le chevron surgit, le curseur s’écrit */
@keyframes introPose{
  0%{opacity:1;transform:none;animation-timing-function:cubic-bezier(.3,0,.6,1)}
  22%{opacity:1;transform:translateY(calc(12*var(--u))) scale(1.025,.97);animation-timing-function:cubic-bezier(.3,0,.4,1)}
  60%{opacity:1;transform:translateY(calc(-4*var(--u)));animation-timing-function:ease-in-out}
  100%{opacity:1;transform:none}}
@keyframes introChevron{from{opacity:0;transform:translateX(calc(-40*var(--u))) scale(.6)}to{opacity:1;transform:none}}
@keyframes introCurseur{from{transform:scaleX(0)}to{transform:none}}
@keyframes introOn{to{opacity:1}}
/* La touche se pose sur les cases soudées pendant les 34 dernières ms (deux images) : aucun fil de jour entre elles ne se voit */
@keyframes introApparait{from{opacity:0}to{opacity:1}}
/* L’appui (au plus bas aux 14 %), puis la plongée : la touche remplit l’écran */
@keyframes introPlonge{
  0%{transform:none;animation-timing-function:cubic-bezier(.3,0,.6,1)}
  14%{transform:translateY(calc(22*var(--u)));animation-timing-function:cubic-bezier(.3,0,.5,1)}
  28%{transform:translateY(calc(14*var(--u))) scale(1.05);animation-timing-function:cubic-bezier(.42,0,.72,.42)}
  100%{transform:translateY(calc(14*var(--u))) scale(9)}}
/* Une lettre : son point vole jusqu’à elle en grandissant, puis s’efface pendant qu’elle apparaît, un peu haute, et se pose */
@keyframes introLettre{
  0%{transform:translate(var(--dx),var(--dy));animation-timing-function:cubic-bezier(.5,0,.2,1)}
  80%{transform:translateY(calc(-10*var(--u))) scale(1.18);animation-timing-function:cubic-bezier(.3,0,.3,1)}
  100%{transform:none}}
/* Le caractère lui-même (dans son <b>) apparaît en opacité, à part : son point, lui, reste visible jusque-là */
@keyframes introLettreTxt{0%,55%{opacity:0}80%,100%{opacity:1}}
/* Le saut du chat : de hors de l’écran, à gauche et plus bas, jusqu’au coin de la touche, en arc ; puis il marche jusqu’au milieu */
@keyframes introSautX{from{transform:translateX(calc(-50vw - 230*var(--u)))}to{transform:translateX(calc(-130*var(--u)))}}
@keyframes introSautY{
  0%{transform:translateY(calc(260*var(--u)));animation-timing-function:cubic-bezier(.2,.6,.4,1)}
  50%{transform:translateY(calc(-190*var(--u)));animation-timing-function:cubic-bezier(.6,0,.8,.4)}
  100%{transform:none}}
@keyframes introMarcheX{from{transform:translateX(calc(-130*var(--u)))}to{transform:none}}
/* La touche qui plie sous le chat, puis son coup de pattes ; il suit l’appui de la touche Entrée */
@keyframes introAtterrit{0%{transform:none;animation-timing-function:cubic-bezier(.3,0,.5,1)}30%{transform:translateY(calc(9*var(--u)));animation-timing-function:cubic-bezier(.3,0,.4,1)}100%{transform:none}}
@keyframes introPatte{0%{transform:none;animation-timing-function:cubic-bezier(.3,0,.6,1)}25%{transform:translateY(calc(14*var(--u)));animation-timing-function:cubic-bezier(.3,0,.4,1)}100%{transform:none}}
@keyframes introChatEntree{
  0%{transform:none;animation-timing-function:cubic-bezier(.3,0,.6,1)}
  14%{transform:translateY(calc(22*var(--u)));animation-timing-function:cubic-bezier(.3,0,.5,1)}
  28%,100%{transform:translateY(calc(14*var(--u)))}}
/* Ses images, une à une : la marche en boucle (12 en 720 ms), l’arrêt une fois (11 pas de 70 ms, puis la dernière reste) */
/* 12 novembre : en paliers plutôt qu’en steps(), que WebKit n’anime jamais hors du fil principal ; en paliers (et linear), le
   compositeur joue seul la marche et l’arrêt du chat, même quand le démarrage occupe le fil pendant l’ouverture. Chaque image reste
   1/12 de la boucle (60 ms) ou 1/11 de l’arrêt (70 ms) ; le saut d’une image à la suivante dure 0,00001 % de l’animation. Les images
   se lisent dans la grille de gauche à droite, rangée après rangée (12 h 24) : -25 % par colonne, -33,33333 % par rangée. */
@keyframes introChatPas{0%,8.33332%{transform:none}8.33333%,16.66666%{transform:translate(-25%,0)}16.66667%,24.99999%{transform:translate(-50%,0)}25%,33.33332%{transform:translate(-75%,0)}33.33333%,41.66666%{transform:translate(0,-33.33333%)}41.66667%,49.99999%{transform:translate(-25%,-33.33333%)}50%,58.33332%{transform:translate(-50%,-33.33333%)}58.33333%,66.66666%{transform:translate(-75%,-33.33333%)}66.66667%,74.99999%{transform:translate(0,-66.66667%)}75%,83.33332%{transform:translate(-25%,-66.66667%)}83.33333%,91.66666%{transform:translate(-50%,-66.66667%)}91.66667%,100%{transform:translate(-75%,-66.66667%)}}
@keyframes introChatAssis{0%,9.0909%{transform:none}9.09091%,18.18181%{transform:translate(-25%,0)}18.18182%,27.27272%{transform:translate(-50%,0)}27.27273%,36.36363%{transform:translate(-75%,0)}36.36364%,45.45454%{transform:translate(0,-33.33333%)}45.45455%,54.54544%{transform:translate(-25%,-33.33333%)}54.54545%,63.63635%{transform:translate(-50%,-33.33333%)}63.63636%,72.72726%{transform:translate(-75%,-33.33333%)}72.72727%,81.81817%{transform:translate(0,-66.66667%)}81.81818%,90.90908%{transform:translate(-25%,-66.66667%)}90.90909%,99.99999%{transform:translate(-50%,-66.66667%)}100%{transform:translate(-75%,-66.66667%)}}
@keyframes introLettreDot{0%{opacity:1;transform:none}50%{opacity:1;transform:scale(1.5)}78%,100%{opacity:0;transform:scale(.5)}}
@keyframes introFade{to{opacity:0}}
@keyframes introGlow{0%{opacity:0;transform:scale(.45)}35%{opacity:1}100%{opacity:0;transform:scale(1.2)}}
@keyframes introOut{to{opacity:0}}
/* Si le moteur SQL ne se charge pas : le message d’erreur, lisible, au centre */
html.is-native.lq #loader.is-intro.fatal{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:16px;padding:32px;animation:none}
html.is-native.lq #loader.is-intro.fatal .logo-badge{position:static;width:88px;height:88px;margin:0;border-radius:26px;background:var(--danger)!important;opacity:1;
  display:flex;align-items:center;justify-content:center;font:700 32px/1 var(--mono);color:#fff;animation:none}
html.is-native.lq #loader.is-intro.fatal .logo-badge::before,html.is-native.lq #loader.is-intro.fatal .logo-badge::after,html.is-native.lq #loader.is-intro.fatal::after,
html.is-native.lq #loader.is-intro.fatal :is(.in-d,.in-s,.in-k,.in-chat){display:none}
html.is-native.lq #loader.is-intro.fatal p{position:static;opacity:1;color:#1B1640}

/* ---------- 38. L’appui : chaque bouton répond ----------
   Elisa, 30 octobre, 23 h 23 : « micro-interaction quand on appuie sur les boutons stp ». Partout, le bouton s’enfonce sous le doigt
   (plus haut) puis rebondit au relâché (assets/curseur.js, sur la vitrine aussi). Ici, ce qui se passe dans les boutons eux-mêmes. */
/* Entretien : l’icône se tasse sous le doigt ; au choix, la coche saute en se dessinant et lâche des confettis, le signet tombe dans
   son bouton, un anneau menthe ou soleil s’échappe du bouton choisi. */
html.lq .ent-focus .ent-assessment .estat{position:relative;overflow:visible;-webkit-tap-highlight-color:transparent}
html.lq .ent-focus .ent-assessment .estat svg{transition:scale .16s var(--press)}
html.lq .ent-focus .ent-assessment .estat:active svg{scale:.78}
html.lq .ent-focus .ent-assessment .estat.ok.is-just svg{animation:lqCheckPop .58s cubic-bezier(.3,1.5,.5,1) both}
html.lq .ent-focus .ent-assessment .estat.ok.is-just svg path{stroke-dasharray:23;animation:lqCheckDraw .4s cubic-bezier(.4,0,.2,1) .08s both}
html.lq .ent-focus .ent-assessment .estat.review.is-just svg{transform-origin:50% 0;animation:lqMarkDrop .62s cubic-bezier(.3,1.3,.5,1) both}
html.lq .ent-focus .ent-assessment .estat.is-just::after{content:"";position:absolute;inset:-2px;border-radius:16px;pointer-events:none;animation:lqRingOut .64s cubic-bezier(.2,.7,.3,1) both}
html.lq .ent-focus .ent-assessment .estat.ok.is-just::after{--lq-ring:98,214,160}
html.lq .ent-focus .ent-assessment .estat.review.is-just::after{--lq-ring:242,194,75}
@keyframes lqRingOut{0%{box-shadow:0 0 0 0 rgba(var(--lq-ring,106,77,244),.6)}100%{box-shadow:0 0 0 13px rgba(var(--lq-ring,106,77,244),0)}}
@keyframes lqCheckPop{0%{scale:.35;rotate:-24deg}55%{scale:1.32;rotate:7deg}100%{scale:1;rotate:0deg}}
@keyframes lqCheckDraw{from{stroke-dashoffset:23}to{stroke-dashoffset:0}}
@keyframes lqMarkDrop{0%{translate:0 -11px;scale:1 .55;opacity:0}45%{translate:0 1px;scale:1 1.14;opacity:1}72%{translate:0 -1px;scale:1 .95}100%{translate:0 0;scale:1 1}}
/* Les confettis s’envolent vers le haut, la gauche et le bas : jamais sur le texte du bouton, à droite de l’icône */
html.lq .lq-burst{position:absolute;z-index:3;width:6px;height:6px;margin:-3px 0 0 -3px;border-radius:50%;pointer-events:none;
  box-shadow:12.7px -12.7px 0 1px #3FC98A,3.1px -17.7px 0 -1px #FFC83D,-7.6px -16.3px 0 0 #6A4DF4,-15.6px -9px 0 1px #FFC83D,-17.9px 1.6px 0 -1px #3FC98A,
    -13.8px 11.6px 0 0 #6A4DF4,-4.7px 17.4px 0 1px #FFC83D,6.2px 16.9px 0 -1px #3FC98A;
  animation:lqBurst .66s cubic-bezier(.15,.8,.3,1) both}
@keyframes lqBurst{0%{scale:.2;opacity:1}65%{opacity:1}100%{scale:1.3;opacity:0}}
/* « Question suivante » : la flèche file vers la droite sous le doigt ; « Révéler la réponse » : l’œil cligne */
html.lq .ent-focus .ent-suite svg{transition:transform .24s cubic-bezier(.3,1.5,.5,1)}
html.lq .ent-focus .ent-suite:active svg{transform:translateX(6px)}
html.lq .ent-reveal-primary:active svg{animation:lqBlink .34s ease-in-out}
@keyframes lqBlink{0%,100%{scale:1 1}40%,55%{scale:1 .1}}
/* La réponse se déplie : l’étiquette saute, le texte et l’exemple montent, puis l’évaluation et « Question suivante » (les flèches de la carte ne bougent pas) */
html.lq .ent-focus.is-reveal .ent-answer-card>.ent-answer-label{animation:lqLabelPop .5s cubic-bezier(.3,1.6,.5,1) both}
html.lq .ent-focus.is-reveal .ent-answer-card>:not(.ent-answer-label){animation:lqRevealIn .42s cubic-bezier(.2,.9,.3,1.1) .07s both}
html.lq .ent-focus.is-reveal .ent-answer-card>.esql{animation-delay:.14s}
html.lq .ent-focus.is-reveal .ent-assessment{animation:lqRevealIn .46s cubic-bezier(.2,.9,.3,1.1) .2s both}
html.lq .ent-focus.is-reveal .ent-suite{animation:lqRevealIn .46s cubic-bezier(.2,.9,.3,1.1) .28s both}
@keyframes lqRevealIn{from{opacity:0;translate:0 12px}to{opacity:1;translate:0 0}}
@keyframes lqLabelPop{0%{opacity:0;scale:.5;rotate:-6deg}60%{opacity:1;scale:1.08;rotate:2deg}100%{opacity:1;scale:1;rotate:0deg}}

@media (prefers-reduced-motion:reduce){
  html.lq .ent-focus .ent-assessment .estat svg,html.lq .ent-focus .ent-assessment .estat svg path,html.lq .ent-focus .ent-assessment .estat::after,html.lq .lq-burst,
  html.lq .ent-reveal-primary:active svg,html.lq .ent-focus.is-reveal .ent-answer-card>*,html.lq .ent-focus.is-reveal .ent-assessment,html.lq .ent-focus.is-reveal .ent-suite,html.lq .ent-focus .ent-pager svg{animation:none!important}
  html.lq .ent-focus .ent-assessment .estat:active svg{scale:none}
  html.lq .ent-focus .ent-suite:active svg{transform:none}
}
html[data-motion="reduce"].lq .ent-focus .ent-assessment .estat svg,html[data-motion="reduce"].lq .ent-focus .ent-assessment .estat svg path,
html[data-motion="reduce"].lq .ent-focus .ent-assessment .estat::after,html[data-motion="reduce"].lq .lq-burst,html[data-motion="reduce"].lq .ent-reveal-primary:active svg,
html[data-motion="reduce"].lq .ent-focus.is-reveal .ent-answer-card>*,html[data-motion="reduce"].lq .ent-focus.is-reveal .ent-assessment,
html[data-motion="reduce"].lq .ent-focus.is-reveal .ent-suite,html[data-motion="reduce"].lq .ent-focus .ent-pager svg{animation:none!important}
html[data-motion="reduce"].lq .ent-focus .ent-assessment .estat:active svg{scale:none}
html[data-motion="reduce"].lq .ent-focus .ent-suite:active svg{transform:none}

/* ---------- 39. Feuilles, page d’un projet, épingles, enregistrement ----------
   Elisa, 31 octobre, 0 h 19 (huit captures) : « regarde la page note pour l’améliorer au niveau de la DA du site », « pareil »
   (Ajuster mon rythme), « la taille change en fonction de l’onglet : je veux que ce soit toujours la même taille d’écran »,
   « micro-interaction quand on enregistre quelque chose, ici ou ailleurs », « améliorer le bouton d’épingle (ici ou ailleurs) »,
   « ce n’est pas responsive, et on ne comprend pas c’est la description de quoi au niveau de la table », « pas assez d’espace entre
   les éléments (juste un petit peu) ». */

/* Toujours la même largeur : la place de la barre de défilement est gardée, qu’il y ait de quoi défiler ou non (barres permanentes,
   souris branchée ; sans effet là où elles s’effacent d’elles-mêmes) */
html.lq .screen,html.lq .viz-body{scrollbar-gutter:stable}

/* Feuilles du bas (Notes, Ajuster mon rythme) : l’en-tête violet quadrillé des feuilles « Description », l’autocollant à gauche */
html.lq .viz.has-cap{overflow:hidden}
html.lq .viz-head.viz-cap{isolation:isolate;overflow:hidden;align-items:center;gap:13px;padding:26px 16px 18px!important;background:var(--deep)!important;border-bottom:0!important;color:#fff}
html.lq .viz-head.viz-cap::before{content:"";position:absolute;inset:0;z-index:-1;pointer-events:none;
  background:radial-gradient(240px 190px at 90% 0%,rgba(255,216,107,.3),transparent 70%),radial-gradient(220px 170px at 0% 100%,rgba(159,240,198,.16),transparent 70%),
    linear-gradient(rgba(255,255,255,.07) 1px,transparent 1px) 0 0/26px 26px,linear-gradient(90deg,rgba(255,255,255,.07) 1px,transparent 1px) 0 0/26px 26px;
  -webkit-mask-image:radial-gradient(ellipse 100% 95% at 60% 10%,#000 35%,transparent 95%);mask-image:radial-gradient(ellipse 100% 95% at 60% 10%,#000 35%,transparent 95%)}
html.lq .viz-head.viz-cap::after{content:"";position:absolute;right:64px;top:22px;width:14px;height:14px;pointer-events:none;background:#fff;
  -webkit-mask:var(--mstk-star) center/contain no-repeat;mask:var(--mstk-star) center/contain no-repeat;animation:lqTwinkle 3.2s ease-in-out infinite}
html.lq .viz-head.viz-cap .grab{background:rgba(255,255,255,.42)!important}
html.lq .viz-cap-stk{flex:none;width:58px;height:58px;margin:-6px -2px -6px -4px;rotate:-7deg}
html.lq .viz-cap-stk svg{display:block;float:none;width:100%;height:100%;margin:0;rotate:0deg;overflow:visible;animation:mstkFloat 5.2s ease-in-out 1.1s infinite}
html.lq .viz-cap-stk.is-in{animation:lqAskSlap .7s cubic-bezier(.3,.7,.3,1) .12s both}
/* 12 novembre, 14 h 59 (capture du schéma d’une base importée, « pare brise 2027 35 cours 70 exercices 3d ») : un titre long passait
   sous l’étoile de l’en-tête. Il s’arrête avant elle, et tient sur deux lignes au plus (la suite en « … »). */
html.lq .viz-cap-t{flex:1;min-width:0;padding-right:20px}
html.lq .viz-head.viz-cap .viz-cap-t b{display:-webkit-box!important;-webkit-box-orient:vertical;-webkit-line-clamp:2;overflow:hidden;overflow-wrap:anywhere}
html.lq .viz-head.viz-cap .viz-cap-t b{display:block;color:var(--sun-hi)!important;font:700 21px/1.12 var(--display)!important;letter-spacing:-.015em!important;outline:none}
html.lq .viz-cap-sub{display:block;margin-top:4px;color:rgba(255,255,255,.88);font:600 13.5px/1.35 var(--display);text-wrap:pretty}
html.lq .viz-cap-sub:empty{display:none}
html.lq .viz-head.viz-cap button{flex:none;align-self:flex-start;margin-top:-4px;background:#fff!important;border:0!important;box-shadow:0 3px 0 rgba(27,22,64,.38)!important;color:#1B1640!important}
html.lq .viz-head.viz-cap button:active{transform:translateY(3px)!important;box-shadow:0 0 0 rgba(27,22,64,.38)!important}
html.lq #plan-adjust-sheet.has-cap .pl-adjust-lead{display:none}
html.lq #plan-adjust-sheet.has-cap .viz-body{padding-top:18px}

/* Notes vides : l’autocollant qui flotte, les trois amorces */
html.lq .notes-empty .ne-i.is-stk{width:82px;height:82px;margin:0 auto 10px;background:none!important;box-shadow:none!important;border-radius:0;rotate:-6deg}
html.lq .notes-empty .ne-i.is-stk svg{display:block;width:100%;height:100%;animation:mstkFloat 5.2s ease-in-out .4s infinite}
html.lq .notes-empty{position:relative;border:2px solid var(--line)!important;border-radius:24px!important;background:#fff!important;box-shadow:0 4px 0 var(--lip)!important}
html.lq .notes-empty::after{content:"";position:absolute;right:22px;top:20px;width:14px;height:14px;pointer-events:none;background:var(--sun);
  -webkit-mask:var(--mstk-star) center/contain no-repeat;mask:var(--mstk-star) center/contain no-repeat;animation:lqTwinkle 3.4s ease-in-out infinite}
html.lq #note-sheet .notes-starters{display:flex;flex-wrap:wrap;justify-content:center;gap:8px;margin-top:16px}
html.lq #note-sheet .notes-starters button{min-height:42px;padding:8px 13px;font:700 14px/1.2 var(--display)}

/* « Ton nouveau parcours » : une fiche blanche à rebord, la cible en autocollant */
html.lq #plan-adjust-sheet .pl-adjust-impact{align-items:center;padding:14px 14px 15px!important;border:2px solid var(--line)!important;background:#fff!important;box-shadow:0 4px 0 var(--lip)}
html.lq #plan-adjust-sheet .pl-impact-icon.is-stk{flex:none;width:50px;height:50px;background:none!important;box-shadow:none!important;border:0!important;rotate:-8deg}
html.lq #plan-adjust-sheet .pl-impact-icon.is-stk svg{display:block;width:100%;height:100%}
html.lq #plan-adjust-sheet .pl-adjust-impact b{color:var(--accent-ink)}
html.lq #plan-adjust-sheet .pl-adjust-impact strong{color:var(--ink)}

/* Enregistré : le bouton passe au menthe, la coche saute en se dessinant (confettis : .lq-burst) */
@keyframes lqSavedPop{0%{scale:.95}45%{scale:1.04}100%{scale:1}}
html.lq .lq-saved{position:relative;overflow:visible!important;pointer-events:none;background:var(--mint)!important;color:#0A6B45!important;border-color:transparent!important;
  box-shadow:0 4px 0 #62D6A0!important;animation:lqSavedPop .5s cubic-bezier(.3,1.5,.5,1) both}
html.lq .lq-saved .lq-saved-ico{display:inline-grid;place-items:center;width:25px;height:25px;margin-right:9px;border-radius:50%;background:#fff;color:#0A6B45;vertical-align:-6px;
  box-shadow:0 2px 0 rgba(10,107,69,.25);animation:lqCheckPop .52s cubic-bezier(.3,1.5,.5,1) both}
html.lq .lq-saved .lq-saved-ico svg{display:block;width:15px;height:15px}
html.lq .lq-saved .lq-saved-ico svg path{stroke-dasharray:23;animation:lqCheckDraw .38s cubic-bezier(.4,0,.2,1) .1s both}
html.lq .ne-row .prim.lq-saved svg{width:15px;height:15px;stroke-dasharray:none;stroke-dashoffset:0}
/* … et ce qu’on vient d’enregistrer s’allume là où il s’affiche */
@keyframes lqFresh{0%{outline:3px solid rgba(255,200,61,.95);outline-offset:0}100%{outline:3px solid rgba(255,200,61,0);outline-offset:10px}}
html.lq .lq-fresh{animation:lqFresh 1.2s cubic-bezier(.2,.7,.3,1)}
/* La notification de réussite : la coche saute et se dessine */
html.lq .toast.on .tmini.ok svg{animation:lqCheckPop .5s cubic-bezier(.3,1.5,.5,1) .05s both}
html.lq .toast.on .tmini.ok svg path{stroke-dasharray:23;animation:lqCheckDraw .36s ease-out .14s both}

/* Épingler : la punaise en autocollant partout (console, historique, notes) ; elle se plante en sautant, se décroche d’un bond */
@keyframes lqPinPlant{0%{translate:0 -12px;rotate:-34deg;scale:1.25}55%{translate:0 2px;rotate:6deg;scale:.92}78%{rotate:-3deg;scale:1.04}100%{translate:0 0;rotate:0deg;scale:1}}
@keyframes lqPinPull{0%{translate:0 0;rotate:0deg}40%{translate:0 -7px;rotate:-24deg}100%{translate:0 0;rotate:-14deg}}
html.lq #scr-console .console-pin-current{position:relative;overflow:visible;display:flex;align-items:center;justify-content:center;gap:10px;width:100%;min-height:54px;margin:0 0 14px;padding:8px 16px;
  border:2px solid var(--line)!important;border-radius:16px!important;background:#fff!important;box-shadow:0 4px 0 var(--lip)!important;color:var(--accent-ink)!important;
  font:700 16px/1.2 var(--display)!important;transition:transform .12s var(--press),box-shadow .12s var(--press),background-color .2s}
html.lq #scr-console .console-pin-current b{font:inherit}
html.lq #scr-console .console-pin-current .console-pin-glyph{display:block;flex:none;width:32px;height:32px;margin:-4px 0;padding:0;border:0;border-radius:0;background:none!important;box-shadow:none!important;rotate:-14deg;transition:rotate .3s var(--pop)}
html.lq #scr-console .console-pin-current .console-pin-glyph svg{display:block;width:100%;height:100%}
html.lq #scr-console .console-pin-current:active:not(:disabled){transform:translateY(4px);box-shadow:0 0 0 var(--lip)!important}
html.lq #scr-console .console-pin-current.on{background:#FFF4D6!important;border-color:#F2C24B!important;box-shadow:0 4px 0 #E8C25C!important;color:#7A5200!important}
html.lq #scr-console .console-pin-current.on .console-pin-glyph{rotate:0deg}
html.lq #scr-console .console-pin-current:disabled{opacity:.5;box-shadow:0 2px 0 var(--lip)!important}
html.lq #scr-console .console-pin-current:disabled .console-pin-glyph{filter:grayscale(1);opacity:.7}
@media (hover:hover) and (pointer:fine){html.lq #scr-console .console-pin-current:hover:not(:disabled) .console-pin-glyph{rotate:-4deg}}
html.lq #scr-console .console-query-pin{position:relative;overflow:visible;width:44px;height:44px;border:2px solid var(--line)!important;border-radius:14px!important;background:#fff!important;box-shadow:0 3px 0 var(--lip)!important;color:inherit}
html.lq #scr-console .console-query-pin svg{width:28px;height:28px;rotate:-14deg;filter:grayscale(.85);opacity:.6;transition:rotate .3s var(--pop),filter .2s,opacity .2s}
html.lq #scr-console .console-query-pin.on{background:#FFF4D6!important;border-color:#F2C24B!important;box-shadow:0 3px 0 #E8C25C!important}
html.lq #scr-console .console-query-pin.on svg{rotate:0deg;filter:none;opacity:1}
html.lq #scr-console .console-query-pin:active{transform:translateY(3px);box-shadow:0 0 0 var(--lip)!important}
html.lq .ncard .npin-btn{position:relative;overflow:visible;border:0!important;background:none!important}
html.lq .ncard .npin-btn svg{width:26px;height:26px;rotate:-14deg;filter:grayscale(.85);opacity:.55;transition:rotate .3s var(--pop),filter .2s,opacity .2s}
html.lq .ncard.pin .npin-btn svg{rotate:0deg;filter:none;opacity:1}
html.lq .ne-row .sec.ne-pin{position:relative;overflow:visible;display:inline-flex;align-items:center;justify-content:center;gap:8px}
html.lq .ne-row .sec.ne-pin svg{width:28px;height:28px;margin:-4px 0;rotate:-14deg;transform:none!important;transition:rotate .3s var(--pop)}
html.lq .ne-row .sec.ne-pin.pin-on{background:#FFF4D6!important;border-color:#F2C24B!important;box-shadow:0 4px 0 #E8C25C!important;color:#7A5200!important}
html.lq .ne-row .sec.ne-pin.pin-on svg{rotate:0deg}
html.lq .is-pin .lq-stk{animation:lqPinPlant .56s cubic-bezier(.3,1.4,.5,1) both}
html.lq .is-unpin .lq-stk{animation:lqPinPull .42s cubic-bezier(.3,.7,.3,1) both}
/* Aucune requête épinglée : la punaise qui flotte */
html.lq #scr-console .console-query-empty .console-query-stk{display:block;width:58px;height:58px;margin:0 auto 8px;rotate:-10deg}
html.lq #scr-console .console-query-empty .console-query-stk svg{display:block;width:100%;height:100%;animation:mstkFloat 5.2s ease-in-out .4s infinite}

/* Page d’un projet : un peu plus d’air entre la carte, les onglets, le schéma et les tables */
html.lq #scr-console .console-title-row.is-project{margin-bottom:16px}
html.lq #scr-console .console-project-tabs{margin-bottom:16px!important}
html.lq #scr-console .console-schema-summary{margin-bottom:14px!important}
html.lq #scr-console .console-schema-panel{margin-bottom:22px!important;gap:14px!important}
html.lq #scr-console .console-schema-panel .db-tables{gap:10px!important}

/* Lignes de tables : le nom en entier (il passe à la ligne s’il le faut), le nombre de lignes dessous, les actions groupées à droite —
