.lst-sub{margin:10px 0 0;max-width:calc(100% - 96px);color:rgba(255,255,255,.88);font:600 16px/1.4 var(--ui)}
.lst-chips{display:flex;flex-wrap:wrap;gap:8px;margin-top:18px;max-width:calc(100% - 70px)}
.lst-chip{display:inline-flex;align-items:center;gap:6px;padding:6px 11px;border-radius:99px;background:rgba(255,255,255,.14);box-shadow:inset 0 0 0 1.5px rgba(255,255,255,.2);
  color:#fff;font:700 13px/1.2 var(--display)}
.lst-chip.is-play{background:#fff;color:var(--accent-ink,#5335E0);box-shadow:0 3px 0 rgba(27,22,64,.28)}
.lst-chip i{font-style:normal;font-size:10px}
.lst-stk{position:absolute;right:-6px;bottom:-26px;width:96px;height:auto;rotate:6deg;filter:drop-shadow(0 6px 0 rgba(27,22,64,.25));pointer-events:none;
  animation:lstStk 3.4s ease-in-out .4s infinite}
.lst-sp{position:absolute;width:14px;height:14px;background:#fff;pointer-events:none;
  clip-path:polygon(50% 0,61% 39%,100% 50%,61% 61%,50% 100%,39% 61%,0 50%,39% 39%);animation:lstSp 2.6s ease-in-out infinite}
.lst-sp.s1{right:76px;top:58px}.lst-sp.s2{right:118px;bottom:40px;width:9px;height:9px;background:var(--sun-hi,#FFD86B);animation-delay:1.2s}
.lst-go{display:flex;align-items:center;justify-content:center;gap:10px;width:100%;min-height:62px;margin:0;border:0;border-radius:20px;background:var(--sun,#FFC83D);
  color:var(--ink,#1B1640);font:800 19px/1 var(--display);box-shadow:0 5px 0 var(--sun-lip,#E0A100);cursor:pointer;transition:transform .12s,box-shadow .12s}
