html.lq #schema-sheet .sch-uml{margin:0 16px 14px}
html.lq #schema-sheet .sch-uml[hidden]{display:none}
html.lq #schema-sheet .umd-tete{display:flex;align-items:baseline;justify-content:space-between;gap:10px;margin:2px 4px 10px}
html.lq #schema-sheet .umd-tete b{font:800 17px/1.2 var(--display);color:var(--ink);letter-spacing:-.01em}
html.lq #schema-sheet .umd-tete span{flex:none;padding:3px 9px;border-radius:99px;background:var(--accent-soft);color:var(--accent-ink);font:700 12px/1.2 var(--display)}
/* Les réglages (7 h 38) : l’interrupteur « Exemples de données », et « Les liens en clair », qui descend jusqu’à la liste. */
html.lq #schema-sheet .umd-outils{display:flex;flex-wrap:wrap;gap:8px;margin:0 2px 12px}
html.lq #schema-sheet .umd-bt{display:inline-flex;align-items:center;gap:8px;min-height:38px;padding:0 13px 0 10px;border:2px solid var(--line);border-radius:99px;background:#fff;box-shadow:0 3px 0 var(--lip);color:var(--ink-2);font:700 13.5px/1 var(--display);cursor:pointer;-webkit-tap-highlight-color:transparent;transition:transform .12s var(--press),box-shadow .12s var(--press),background .2s,border-color .2s,color .2s}
html.lq #schema-sheet .umd-bt:active{transform:translateY(3px);box-shadow:0 0 0 var(--lip)}
html.lq #schema-sheet .umd-bt>svg{flex:none;width:17px;height:17px;color:var(--accent)}
html.lq #schema-sheet .umd-bt:focus-visible{outline:3px solid var(--accent);outline-offset:2px}
