html.lq #schema-sheet .umd-sw::after{content:"";position:absolute;top:2px;left:2px;width:14px;height:14px;border-radius:50%;background:#fff;box-shadow:0 1px 2px rgba(27,22,64,.28);transition:transform .22s cubic-bezier(.3,.7,.4,1.3)}
html.lq #schema-sheet .umd-bt.is-ex[aria-pressed="true"]{border-color:#D9D0FF;background:var(--accent-soft);color:var(--accent-ink)}
html.lq #schema-sheet .umd-bt.is-ex[aria-pressed="true"] .umd-sw{background:var(--accent)}
html.lq #schema-sheet .umd-bt.is-ex[aria-pressed="true"] .umd-sw::after{transform:translateX(12px)}
html.lq #schema-sheet .umd-toile{position:relative;overflow:hidden;border-radius:22px;background-color:#FBFAFF;
