/* Sur un trait allumé, des points qui coulent de la clé étrangère vers la clé primaire : le sens du lien (9 h 18 : « une flèche animée ») */
html.lq #schema-sheet .umd-f{fill:none;stroke:#fff;stroke-width:1.7;stroke-linecap:round;stroke-dasharray:.1 7;opacity:0;pointer-events:none;transition:opacity .2s}
html.lq #schema-sheet .umd-f:is(.is-on,.is-sur){opacity:.95;animation:umdFlux .75s linear infinite}
@keyframes umdFlux{to{stroke-dashoffset:-7.1}}
html.lq #schema-sheet .umd-plan.is-focus .umd-m:not(.is-on){opacity:.16}
html.lq #schema-sheet .umd-t{position:absolute;display:flex;flex-direction:column;margin:0;padding:0;border:0;border-radius:16px;background:#fff;box-shadow:0 3px 0 var(--lip);
  overflow:hidden;color:var(--ink);font:inherit;text-align:left;cursor:pointer;-webkit-tap-highlight-color:transparent;transition:transform .12s var(--press),box-shadow .12s var(--press),opacity .2s,filter .2s}
html.lq #schema-sheet .umd-t::after{content:"";position:absolute;inset:0;border-radius:inherit;box-shadow:inset 0 0 0 2px var(--line);pointer-events:none;transition:box-shadow .2s}
html.lq #schema-sheet .umd-t:active:not(:has(.umd-pli:active)){transform:translateY(3px);box-shadow:0 0 0 var(--lip)}
html.lq #schema-sheet .umd-hb:focus-visible,html.lq #schema-sheet .umd-pli:focus-visible{outline:3px solid var(--accent);outline-offset:-3px}
