html.lq #schema-sheet .umd-plan.is-focus .umd-t:not(.is-sel):not(.is-lie){opacity:.4;filter:saturate(.35)}
html.lq #schema-sheet .umd-h{flex:none;display:flex;align-items:center;gap:6px;height:34px;padding:0 5px 0 14px;background:var(--cs);box-shadow:inset 4px 0 0 var(--c),inset 0 -2px 0 var(--line)}
