html.lq #schema-sheet .umd-hb{flex:1;min-width:0;display:flex;align-items:center;gap:8px;height:100%;margin:0;padding:0;border:0;background:none;color:inherit;font:inherit;text-align:left;cursor:pointer;-webkit-tap-highlight-color:transparent}
html.lq #schema-sheet .umd-pli{flex:none;display:grid;place-items:center;width:28px;height:28px;margin:0;padding:0;border:0;border-radius:50%;background:rgba(255,255,255,.75);color:var(--ci);cursor:pointer;-webkit-tap-highlight-color:transparent;transition:background .15s,transform .12s var(--press)}
html.lq #schema-sheet .umd-pli:active{transform:scale(.9)}
html.lq #schema-sheet .umd-pli svg{width:15px;height:15px;transition:transform .32s cubic-bezier(.33,1,.68,1)}
html.lq #schema-sheet .umd-t.is-plie .umd-pli svg{transform:rotate(-90deg)}
html.lq #schema-sheet .umd-h b{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font:800 13px/34px var(--mono);color:var(--ci)}
