html.lq #plus-pacte .ob-pact-stamp{position:absolute;right:14px;top:-14px;padding:6px 12px;border-radius:12px;background:var(--v-mint);color:var(--v-ink);font:800 13px/1 var(--v-display);
  box-shadow:0 3px 0 rgba(27,22,64,.25);rotate:8deg;opacity:0;transform:scale(1.6);pointer-events:none;transition:opacity .2s,transform .35s var(--v-pop)}
html.lq #plus-pacte .ob-pact-card.is-signed .ob-pact-stamp{opacity:1;transform:none}
html.lq #plus-pacte .ob-hold-zone{display:flex;flex-direction:column;align-items:center;gap:16px;margin:20px 0 4px}
html.lq #plus-pacte .ob-hold-hint{display:flex;align-items:center;justify-content:center;min-height:2.7em;margin:0;max-width:300px;color:rgba(255,255,255,.86);font:650 14.5px/1.35 var(--v-ui);text-align:center;text-wrap:balance}
html.lq #plus-pacte .ob-hold-hint.is-relance{color:var(--v-sun-hi)}
html.lq #plus-pacte .ob-hold{position:relative;display:grid;place-items:center;width:96px;height:96px;margin:9px 0 16px;padding:0;border:0;border-radius:50%;
  background:var(--v-sun);color:#1B1640;box-shadow:0 6px 0 var(--v-sun-lip),0 16px 30px -12px rgba(27,22,64,.6);cursor:pointer;touch-action:none;
  -webkit-touch-callout:none;-webkit-user-select:none;user-select:none;-webkit-tap-highlight-color:transparent;transition:transform .16s var(--v-press),box-shadow .16s var(--v-press),background .3s}
html.lq #plus-pacte .ob-hold::before{content:'';position:absolute;inset:-12px;border-radius:50%;background:rgba(255,216,107,.28);pointer-events:none}
