/* ---------- Retours du 5 novembre, 22 h 19 ----------
   « Projet importé » (réf. 2 : « une micro-interaction en mode validé ») : la coche du compte rendu rebondit en tournant, une onde
   verte part d’elle, et les tables arrivent une à une (net, après un léger flou) ; la coche « Importé » se pose sur la carte
   (lqDone). Rien en mouvement réduit. */
@media (prefers-reduced-motion:no-preference){
  html.lq:not([data-motion="reduce"]) #console-out .feedback.ok.is-valide .fi{position:relative;animation:lqImpCoche .55s cubic-bezier(.3,1.5,.5,1) .05s backwards}
  html.lq:not([data-motion="reduce"]) #console-out .feedback.ok.is-valide .fi::after{content:'';position:absolute;inset:-2px;border-radius:50%;box-shadow:0 0 0 0 rgba(22,163,74,.45);animation:lqImpOnde .9s ease-out .25s both}
  html.lq:not([data-motion="reduce"]) #console-out .feedback.ok.is-valide code{animation:lqImpTable .38s ease-out calc(.2s + var(--i,0) * 55ms) backwards}
  html.lq:not([data-motion="reduce"]) #console-out .feedback.ok.is-valide .imp-uml{animation:lqImpUml .42s cubic-bezier(.3,1.4,.5,1) .55s backwards}
}
@keyframes lqImpCoche{0%{transform:scale(0) rotate(-40deg)}60%{transform:scale(1.25) rotate(8deg)}100%{transform:none}}
