@keyframes mcPop{0%{opacity:0;transform:scale(.3) rotate(-30deg)}70%{opacity:1;transform:scale(1.08)}100%{opacity:1;transform:none}}
@keyframes mcTurn{0%,62%,100%{rotate:0deg}80%{rotate:-200deg}}
@keyframes mcWobble{0%,100%{rotate:6deg}30%{rotate:-4deg}60%{rotate:9deg}}
@keyframes mcFloat{0%,100%{translate:0 0}50%{translate:0 -4px}}
