html.lq .mc-prize-t{margin:-12px -8px 0 0;padding:5px 8px;border:2px solid #fff;border-radius:9px;background:var(--sun);color:var(--mc-ink);font:800 12px/1 var(--display);white-space:nowrap;box-shadow:0 3px 0 var(--sun-lip);rotate:-7deg}
