html.lq .dx-feuille .dx-duel-voir{display:inline-flex;align-items:center;justify-content:center;gap:4px;min-height:36px;margin:6px auto 0;padding:4px 10px;border:0;border-radius:10px;background:none;color:var(--ink-2);font:700 13px/1.2 var(--ui)}
