html.lq #scr-defis .dx-ancre{display:inline-flex;align-items:center;gap:4px;min-height:44px;margin:0 0 -8px;padding:0 2px;border:0;background:none;color:var(--accent-ink);font:800 14px/1.2 var(--ui);text-align:left;cursor:pointer;-webkit-tap-highlight-color:transparent}
