@keyframes dxXEtincelle{0%{opacity:0;transform:translate(0,0) scale(.3) rotate(0)}20%{opacity:1}75%{opacity:1}100%{opacity:0;transform:translate(var(--dx),var(--dy)) scale(1) rotate(100deg)}}
