html.lq #scr-defis .dx-list .dx-t small.dx-pcs .dx-pc .jeu-bars{height:10px}
html.lq #scr-defis .dx-list .dx-t small.dx-pcs .dx-pc .jeu-bars b:nth-child(1){height:3.5px}
html.lq #scr-defis .dx-list .dx-t small.dx-pcs .dx-pc .jeu-bars b:nth-child(2){height:6.5px}
