  background:radial-gradient(220px 160px at 92% 0%,rgba(255,216,107,.3),transparent 70%),radial-gradient(200px 150px at 0% 100%,rgba(159,240,198,.18),transparent 70%),
    linear-gradient(rgba(255,255,255,.07) 1px,transparent 1px) 0 0/22px 22px,linear-gradient(90deg,rgba(255,255,255,.07) 1px,transparent 1px) 0 0/22px 22px}
